1. 购物车系统设计：

```python
class Product:
    def __init__(self, product_id, name, price):
        self.product_id = product_id
        self.name = name
        self.price = price

class ShoppingCart:
    def __init__(self):
        self.items = {}  # 使用字典存储商品，键为商品ID，值为包含商品对象和数量的字典

    def add_item(self, product, quantity=1):
        if product.product_id in self.items:
            self.items[product.product_id]['quantity'] += quantity
        else:
            self.items[product.product_id] = {
                'product': product,
                'quantity': quantity
            }

    def remove_item(self, product_id):
        if product_id in self.items:
            del self.items[product_id]

    def update_quantity(self, product_id, new_quantity):
        if product_id in self.items and new_quantity > 0:
            self.items[product_id]['quantity'] = new_quantity
        elif product_id in self.items and new_quantity <= 0:
            self.remove_item(product_id)

    def calculate_total(self):
        total = 0
        for item in self.items.values():
            total += item['product'].price * item['quantity']
        return total

    def apply_discount(self, discount_type, discount_value):
        if discount_type == "percentage":
            return self.calculate_total() * (1 - discount_value/100)
        elif discount_type == "fixed":
            return max(0, self.calculate_total() - discount_value)
        return self.calculate_total()
```

